mapper.sql:
WHERE (sales_orders.status >= 0 OR sales_orders.status = -2) AND sales_orders.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})

    AND sales_orders.created_by = #{userId}


    AND sales_orders.type = #{filter.type}


    AND sales_orders.id NOT IN (SELECT sales_order_id FROM delivery_details WHERE delivery_id IS NOT NULL)


    AND sales_orders.location_group_id = #{filter.warehouseId}


    AND sales_orders.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})


    AND sales_orders.customer_id = #{filter.organizationId}


    AND sales_orders.order_date >= #{filter.dateFrom}


    AND sales_orders.order_date <= #{filter.dateTo}


    AND sales_orders.status = #{filter.status}


    AND sales_orders.is_pos = #{filter.isPos}




            AND sales_orders.balance > 0


            AND sales_orders.balance = 0




    AND (sales_orders.so_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.customer_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.name_kh LIKE CONCAT('%', #{filter.searchText}, '%')
    OR sales_orders.order_number LIKE CONCAT('%', #{filter.searchText}, '%')
    OR (SELECT cm_code FROM credit_memos WHERE credit_memos.sales_order_id = sales_orders.id AND credit_memos.status > 0 LIMIT 1) LIKE CONCAT('%', #{filter.searchText}, '%')
    )

