UPDATE sales_order_details
po_no = #{detail.poNo}, qty = #{detail.qty}, qty_free = #{detail.qtyFree}, conversion = #{detail.conversion}, qty_uom_id = #{detail.uomId}, discount_id = #{detail.discountId}, discount_amount = #{detail.discountAmount}, discount_percent = #{detail.discountPercent}, unit_price = #{detail.unitPrice}, total_price = #{detail.totalPrice}, note = #{detail.note}, modified = NOW(), modified_by = #{detail.modifiedBy}
WHERE sales_order_id = #{detail.saleInvoiceId} AND product_id = #{detail.itemId}

UPDATE sales_order_services
po_no = #{service.poNo}, qty = #{service.qty}, qty_free = #{service.qtyFree}, discount_id = #{service.discountId}, month = #{service.month}, start = #{service.startDate}, discount_amount = #{service.discountAmount}, discount_percent = #{service.discountPercent}, unit_price = #{service.unitPrice}, total_price = #{service.totalPrice}, note = #{service.note}, modified = NOW(), modified_by = #{service.modifiedBy}
WHERE sales_order_id = #{service.saleInvoiceId} AND service_id = #{service.itemId}

UPDATE sales_order_miscs
description = #{misc.itemName}, po_no = #{misc.poNo}, qty = #{misc.qty}, qty_uom_id = #{misc.uomId}, qty_free = #{misc.qtyFree}, discount_id = #{misc.discountId}, discount_amount = #{misc.discountAmount}, discount_percent = #{misc.discountPercent}, unit_price = #{misc.unitPrice}, total_price = #{misc.totalPrice}, note = #{misc.note}, deposit_coa_id = #{misc.depositCoaId}, modified = NOW(), modified_by = #{misc.modifiedBy}
WHERE sales_order_id = #{misc.saleInvoiceId} AND description = #{misc.itemName}

