mapper.select:
SELECT SUM(total_qty)
FROM ${tableName}
WHERE product_id = #{productId}
  AND location_group_id = #{warehouseId}
  AND location_id IN (SELECT id FROM locations WHERE location_group_id = #{warehouseId}

        AND is_for_sale = 1

)

SELECT SUM(sor.qty) AS total_order
FROM stock_orders AS sor
INNER JOIN sales_orders AS so ON so.id = sor.sales_order_id

    AND so.id != #{salesInvoiceId}

WHERE sor.product_id = #{productId}
AND sor.location_group_id = #{warehouseId}
GROUP BY sor.product_id

SELECT deposit_coa_id
FROM sales_order_miscs
WHERE sales_order_id = #{saleInvoiceId}

SELECT IFNULL(total_price,0)
FROM sales_order_miscs
WHERE sales_order_id = #{saleInvoiceId}

