UPDATE sales_orders
SET is_close_deposit = 1
WHERE id = #{saleInvoiceId}

UPDATE quotations
SET total_deposit = total_deposit + #{totalDeposit}
WHERE id = #{quotationId}

UPDATE orders SET
    is_close = 1,
    modified = NOW(),
    modified_by = #{userId}
WHERE id = #{saleOrderId}

UPDATE ${tableName}
SET total_order = total_order + #{qty}
WHERE location_id = #{locationId}
  AND product_id = #{productId}
  AND lots_number = #{lotsNumber}
  AND expired_date = #{expiredDate}

