SELECT COUNT(*) AS total
FROM (
         SELECT id FROM sales_order_details WHERE sales_order_id = #{saleInvoiceId}
         UNION ALL
         SELECT id FROM sales_order_services WHERE sales_order_id = #{saleInvoiceId}
         UNION ALL
         SELECT id FROM sales_order_miscs WHERE sales_order_id = #{saleInvoiceId}
     ) AS combined

SELECT IFNULL(COUNT(delivery_id),0)
FROM sales_orders
WHERE sales_order_id = #{saleInvoiceId}

